58		);
59		const [judging, setJudging] = useState(false);
60		const { state, audioBlob, start, stop, reset } = useMicRecorder();
61		const audioRef = useRef<HTMLAudioElement | null>(null);
62	
63		useEffect(() => {
64			let cancelled = false;
65			// The learner's real known-vocabulary snapshot, sourced from their
66			// SRS state — never a placeholder list. A learner with nothing
67			// learned yet sends a real empty array, not an omitted field.
68			const knownWords = vocab.getLearnedEntries().map((entry) => entry.thai);
69			conversationPractice.getOpening(knownWords).then((result) => {
70				if (!cancelled) setOpening(result);
71			});
72			return () => {
73				cancelled = true;
74			};
75		}, [conversationPractice, vocab]);
76	
77		const questionText = opening?.status === "ok" ? opening.questionText : null;
78		const questionAudioUrl =
79			opening?.status === "ok" ? opening.questionAudioUrl : null;
80	
81		// One finished take → one judgement. Keyed on the blob's identity, so a
82		// re-render never re-submits the same recording.
83		useEffect(() => {
84			if (state !== "stopped" || !audioBlob || !questionText) return;
85			let cancelled = false;
86			setJudging(true);
87			conversationPractice.judgeReply(questionText, audioBlob).then((result) => {
88				if (cancelled) return;
89				setJudgement(result);
90				setJudging(false);
91			});
92			return () => {
93				cancelled = true;
94			};
95		}, [state, audioBlob, questionText, conversationPractice]);
96	
97		// Same replay convention as SentenceListeningChallenge /
98		// SymbolDictationChallenge: a fresh `Audio` per press, the previous one
99		// stopped first, rejections swallowed (autoplay policy).
100		const playQuestion = useCallback(() => {
101			if (!questionAudioUrl) return;
102			if (audioRef.current) {
103				audioRef.current.pause();
104				audioRef.current.currentTime = 0;
105			}
106			const audio = new Audio(questionAudioUrl);
107			audioRef.current = audio;
108			audio.play().catch(() => {});
109		}, [questionAudioUrl]);
110	
111		useEffect(
112			() => () => {
113				audioRef.current?.pause();
114				audioRef.current = null;
115			},
116			[],
117		);
118	
119		function tryAgain() {
120			setJudgement(null);
121			reset();
122		}
123	
124		if (opening === null) {
125			return <p className="p-4">Connecting to the conversation backend…</p>;
126		}
127	
128		// No question means nothing to reply to — so no record control at all,
129		// rather than one that would silently do nothing.
130		if (opening.status === "unavailable") {
131			return (
132				<div className="space-y-4 p-4">
133					<h1 className="text-xl font-semibold">Conversation practice</h1>
134					<p role="alert">{BACKEND_UNAVAILABLE_MESSAGE}</p>
135				</div>
136			);
137		}
